<?php $e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); ?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Moderation – MeldeVerkehr</title><style>body{font-family:system-ui,sans-serif;background:#f5f7fa;color:#172033;margin:0}main{max-width:1000px;margin:28px auto;padding:20px}.card{background:#fff;border:1px solid #dfe5ec;border-radius:15px;padding:20px;margin-bottom:14px}.item{border-top:1px solid #e5e9ee;padding:12px 0}button{padding:8px 12px;border:0;border-radius:8px;background:#172033;color:white;font-weight:700}select,input{padding:8px;border:1px solid #bac5d1;border-radius:8px}.message,.error{padding:10px;border-radius:8px}.message{border:1px solid #8fb799}.error{border:1px solid #c99}</style></head><body><main><p><a href="/community">← Community</a></p><h1>Moderation</h1><?php if($message):?><div class="message"><?= $e($message) ?></div><?php endif;?><?php if($error):?><div class="error"><?= $e($error) ?></div><?php endif;?>
<section class="card"><h2>Neue öffentliche Problemstellen</h2><?php foreach($pendingProblems as $p):?><div class="item"><strong><?= $e($p['name']) ?></strong> · @<?= $e($p['username']??'') ?> · <?= $e($p['city']??'') ?><form method="post" action="/community/moderation/problems/<?= rawurlencode($p['id']) ?>/approve"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><button type="submit">Freigeben</button></form></div><?php endforeach;?></section>
<section class="card"><h2>Gemeldete Inhalte</h2><?php foreach($reports as $r):?><div class="item"><strong><?= $e($r['target_type']) ?></strong> · <?= $e($r['category']) ?> · gemeldet von @<?= $e($r['reporter_username']??'') ?><p><?= $e($r['reason']??'') ?></p><form method="post" action="/community/moderation/reports/<?= rawurlencode($r['id']) ?>/resolve"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><select name="action"><option>DISMISS</option><option>HIDE</option><option>WARN</option><option>RESTRICT</option></select><input name="reason" placeholder="Begründung"><button type="submit">Abschließen</button></form></div><?php endforeach;?></section>
</main></body></html>